#!/bin/bash
# DEPLOY_v2_close3 — أولوية جوار القانون + عدّادا المرتِّب، ثم Smoke ← Full Gate
set -u
cd /opt/LegalMind || exit 1
cat > /tmp/v2c3.b64 <<'B64EOF'

B64EOF
base64 -d /tmp/v2c3.b64 > /tmp/v2c3.tgz || { echo "B64_FAIL"; exit 1; }
tar xzf /tmp/v2c3.tgz -C /opt/LegalMind || { echo "UNTAR_FAIL"; exit 1; }
